P={{CLAUDE}}/../packs; [ -d "$P" ] || { printf 'ok (skipped: no packs/ beside claude/ - a deployed harness)'; exit 0; }; python3 - "$P/dev" "$P/repo-orkeon" <<'EOF'
import os, sys, unicodedata
bad = []
for top in sys.argv[1:]:
    for d, _, fs in os.walk(top):
        for n in fs:
            p = os.path.join(d, n)
            t = open(p, encoding='utf-8', errors='replace').read()
            hits = sorted({c for c in t if ord(c) > 127 and unicodedata.category(c).startswith('L')})
            if hits:
                bad.append(os.path.relpath(p, top) + '=' + ''.join(hits).encode('ascii', 'backslashreplace').decode())
print(' '.join('BAD-accented:' + b for b in bad) or 'ok')
EOF
